sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Only measure MAT0001748
    var targetMatchSysId = '6e6da3b2d56f43107f4491472fd3df69';

    if (current.getUniqueValue() != targetMatchSysId) {
        return;
    }

    // We only care about the exact transition:
    // PI Pending = true  ->  false
    if (previous.getValue('pi_pending') != '1') {
        return;
    }

    if (current.getValue('pi_pending') != '0') {
        return;
    }

    // Make sure the PI values are actually populated
    var imageScore = current.getValue('image_similarity');
    var descriptionScore = current.getValue('description_similarity');
    var uniqueScore = current.getValue('unique_attribute_score');

    if (!imageScore || !descriptionScore || !uniqueScore) {
        return;
    }

    // Read the measurement start timestamp
    var startValue = gs.getProperty(
        'x_snc_campusmatch.pi_measurement_start'
    );

    if (!startValue) {
        gs.warn(
            'CampusMatch PI Measurement: Start timestamp not found.'
        );
        return;
    }

    var startTime = new GlideDateTime(startValue);
    var endTime = new GlideDateTime();

    var elapsedMilliseconds =
        endTime.getNumericValue() -
        startTime.getNumericValue();

    var elapsedSeconds =
        elapsedMilliseconds / 1000;

    gs.info('========================================');
    gs.info('CampusMatch PI PERFORMANCE MEASUREMENT');
    gs.info('========================================');
    gs.info('Match: ' + current.getDisplayValue());
    gs.info('Start Time: ' + startTime.getDisplayValue());
    gs.info('Completion Time: ' + endTime.getDisplayValue());
    gs.info('Elapsed Time: ' + elapsedSeconds.toFixed(3) + ' seconds');
    gs.info('Image Similarity: ' + imageScore);
    gs.info('Description Similarity: ' + descriptionScore);
    gs.info('Unique Attribute Score: ' + uniqueScore);
    gs.info('Overall Score: ' + current.getValue('overall_score'));
    gs.info('PI Pending: ' + current.getValue('pi_pending'));
    gs.info('========================================');

})(current, previous);
